{"implementation":"def solve(case):
    import collections, math, json

    nodes = case['nodes']
    core = case['core_distance']
    dist_entries = case['distances']

    node_to_idx = {n: i for i, n in enumerate(nodes)}

    edges = []
    for u, v, d in dist_entries:
        if u > v:
            u, v = v, u
        w = max(core[u], core[v], d)
        edges.append((w, u, v))

    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    parent = list(range(len(nodes)))
    rank = [0]*len(nodes)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for w, u, v in edges:
        iu, iv = node_to_idx[u], node_to_idx[v]
        if union(iu, iv):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break

    if len(mst_edges) != len(nodes) - 1:
        raise ValueError("Input graph is disconnected")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }"}
